--- /dev/null
+++ b/acceptance/acceptance_test.go
@@ -0,0 +1,456 @@
+package acceptance_test
+
+import (
+	"bytes"
+	"encoding/json"
+	"fmt"
+	"image/png"
+	"io"
+	"net/http"
+	"net/http/cookiejar"
+	"net/http/httptest"
+	"strings"
+	"testing"
+
+	"git.aisoftwarefactory.world/linkshort4/linkshort4/internal/server"
+)
+
+func newTestServer(t *testing.T) *httptest.Server {
+	t.Helper()
+	app := server.New(server.Config{DataDir: t.TempDir()})
+	srv := httptest.NewServer(app)
+	t.Cleanup(func() {
+		srv.Close()
+		app.Close()
+	})
+	return srv
+}
+
+func newClient() *http.Client {
+	jar, _ := cookiejar.New(nil)
+	return &http.Client{Jar: jar}
+}
+
+func signup(t *testing.T, client *http.Client, srvURL, email, password string) {
+	t.Helper()
+	body := fmt.Sprintf(`{"email":%q,"password":%q}`, email, password)
+	res, err := client.Post(srvURL+"/api/signup", "application/json", strings.NewReader(body))
+	if err != nil {
+		t.Fatal(err)
+	}
+	b, _ := io.ReadAll(res.Body)
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusCreated {
+		t.Fatalf("signup %s: status %d, want 201; body: %s", email, res.StatusCode, b)
+	}
+}
+
+func login(t *testing.T, client *http.Client, srvURL, email, password string) {
+	t.Helper()
+	body := fmt.Sprintf(`{"email":%q,"password":%q}`, email, password)
+	res, err := client.Post(srvURL+"/api/login", "application/json", strings.NewReader(body))
+	if err != nil {
+		t.Fatal(err)
+	}
+	b, _ := io.ReadAll(res.Body)
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusOK {
+		t.Fatalf("login %s: status %d, want 200; body: %s", email, res.StatusCode, b)
+	}
+}
+
+func TestA1SignupLoginMeLogout(t *testing.T) {
+	srv := newTestServer(t)
+	client := newClient()
+
+	signup(t, client, srv.URL, "user@example.com", "password1234")
+
+	res, err := client.Get(srv.URL + "/api/me")
+	if err != nil {
+		t.Fatal(err)
+	}
+	b, _ := io.ReadAll(res.Body)
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusOK {
+		t.Fatalf("GET /api/me after signup: status %d, want 200; body: %s", res.StatusCode, b)
+	}
+	var me map[string]string
+	if err := json.Unmarshal(b, &me); err != nil {
+		t.Fatalf("unmarshal /api/me: %v", err)
+	}
+	if me["email"] != "user@example.com" {
+		t.Errorf("/api/me email = %q, want user@example.com", me["email"])
+	}
+
+	logoutReq, err := http.NewRequest("POST", srv.URL+"/api/logout", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	logoutRes, err := client.Do(logoutReq)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = logoutRes.Body.Close()
+	if logoutRes.StatusCode != http.StatusNoContent {
+		t.Errorf("logout: status %d, want 204", logoutRes.StatusCode)
+	}
+
+	login(t, client, srv.URL, "user@example.com", "password1234")
+
+	res2, err := client.Get(srv.URL + "/api/me")
+	if err != nil {
+		t.Fatal(err)
+	}
+	b2, _ := io.ReadAll(res2.Body)
+	_ = res2.Body.Close()
+	if res2.StatusCode != http.StatusOK {
+		t.Fatalf("GET /api/me after login: status %d, want 200; body: %s", res2.StatusCode, b2)
+	}
+
+	logoutReq2, err := http.NewRequest("POST", srv.URL+"/api/logout", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	logoutRes2, err := client.Do(logoutReq2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = logoutRes2.Body.Close()
+
+	meReq, err := http.NewRequest("GET", srv.URL+"/api/me", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	meRes, err := client.Do(meReq)
+	if err != nil {
+		t.Fatal(err)
+	}
+	meB, _ := io.ReadAll(meRes.Body)
+	_ = meRes.Body.Close()
+	if meRes.StatusCode != http.StatusUnauthorized {
+		t.Errorf("GET /api/me after logout: status %d, want 401; body: %s", meRes.StatusCode, meB)
+	}
+}
+
+func TestA2CreateRedirectList(t *testing.T) {
+	srv := newTestServer(t)
+	client := newClient()
+	signup(t, client, srv.URL, "linkuser@example.com", "password1234")
+
+	createBody := `{"url":"https://example.com","slug":"mylink"}`
+	res, err := client.Post(srv.URL+"/api/links", "application/json", strings.NewReader(createBody))
+	if err != nil {
+		t.Fatal(err)
+	}
+	cb, _ := io.ReadAll(res.Body)
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusCreated {
+		t.Fatalf("create link: status %d, want 201; body: %s", res.StatusCode, cb)
+	}
+
+	noRedirectClient := &http.Client{
+		CheckRedirect: func(_ *http.Request, _ []*http.Request) error {
+			return http.ErrUseLastResponse
+		},
+		Jar: client.Jar,
+	}
+	redirRes, err := noRedirectClient.Get(srv.URL + "/mylink")
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = redirRes.Body.Close()
+	if redirRes.StatusCode != http.StatusFound {
+		t.Errorf("GET /mylink: status %d, want 302", redirRes.StatusCode)
+	}
+	loc := redirRes.Header.Get("Location")
+	if loc != "https://example.com" {
+		t.Errorf("Location = %q, want https://example.com", loc)
+	}
+
+	listRes, err := client.Get(srv.URL + "/api/links")
+	if err != nil {
+		t.Fatal(err)
+	}
+	lb, _ := io.ReadAll(listRes.Body)
+	_ = listRes.Body.Close()
+	if listRes.StatusCode != http.StatusOK {
+		t.Fatalf("list links: status %d, want 200; body: %s", listRes.StatusCode, lb)
+	}
+	var links []struct {
+		Slug   string `json:"slug"`
+		URL    string `json:"url"`
+		Clicks int64  `json:"clicks"`
+	}
+	if err := json.Unmarshal(lb, &links); err != nil {
+		t.Fatalf("unmarshal links: %v", err)
+	}
+	if len(links) != 1 {
+		t.Fatalf("expected 1 link, got %d", len(links))
+	}
+	if links[0].Clicks != 1 {
+		t.Errorf("clicks = %d, want 1", links[0].Clicks)
+	}
+}
+
+func TestA3SlugConflictBadScheme(t *testing.T) {
+	srv := newTestServer(t)
+	client := newClient()
+	signup(t, client, srv.URL, "conflict@example.com", "password1234")
+
+	createBody := `{"url":"https://example.com","slug":"taken"}`
+	res, err := client.Post(srv.URL+"/api/links", "application/json", strings.NewReader(createBody))
+	if err != nil {
+		t.Fatal(err)
+	}
+	_ = res.Body.Close()
+	if res.StatusCode != http.StatusCreated {
+		t.Fatalf("first create: status %d, want 201", res.StatusCode)
+	}
+
+	dupBody := `{"url":"https://other.com","slug":"taken"}`
+	dupRes, err := client.Post(srv.URL+"/api/links", "application/json", strings.NewReader(dupBody))
+	if err != nil {
+		t.Fatal(err)
+	}
+	db, _ := io.ReadAll(dupRes.Body)
+	_ = dupRes.Body.Close()
+	if dupRes.StatusCode != http.StatusConflict {
+		t.Errorf("duplicate slug: status %d, want 409; body: %s", dupRes.StatusCode, db)
+	}
+
+	ftpBody := `{"url":"ftp://files.example.com/file.txt","slug":"ftplink"}`
+	ftpRes, err := client.Post(srv.URL+"/api/links", "application/json", strings.NewReader(ftpBody))
+	if err != nil {
+		t.Fatal(err)
+	}
+	fb, _ := io.ReadAll(ftpRes.Body)
+	_ = ftpRes.Body.Close()
+	if ftpRes.StatusCode != http.StatusBadRequest {
+		t.Errorf("ftp url: status %d, want 400; body: %s", ftpRes.StatusCode, fb)
+	}
+}
+
