cd /workspace/repo && cat > /tmp/test_remote.go << 'EOF'
package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
)

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Println("RemoteAddr:", r.RemoteAddr)
		w.WriteHeader(200)
	}))
	defer srv.Close()
	for i := 0; i < 3; i++ {
		http.Get(srv.URL)
	}
}
EOF
go run /tmp/test_remote.go

